mutations.find:
def _unpaid(session: Session, driver_id: int) -> list[CommissionDebt]:
    return session.exec(
        select(CommissionDebt).where(
            CommissionDebt.driver_id == driver_id,
            CommissionDebt.status == DebtStatus.unpaid,
        )
    ).all()

